find.example:
const { Buffs } = kcds.players;

const drunk = Buffs.find('drunk');
const blessing = Buffs.find('myres:blessing');

register.example:
const blessing = kcds.players.Buffs.register('myres:blessing', {
  name: 'Blessing',
  description: 'A priest blessed you.',
  visual: 'well_rested',
  duration: 120,
  tickInterval: 10,
  modifiers: { stamina: 20, hunger: { operation: 'set', value: 100 }, healthRegeneration: 0.5 },
});

kcds.core.Events.on('playerCustomBuffTick', (target, buff) => {
  console.info(`${buff.displayName} ticks on ${target.nickname}`);
});

player.addBuff(blessing);

register.exampleCs:
var blessing = Buffs.Register("myres:blessing", new { name = "Blessing", description = "A priest blessed you.", visual = "well_rested", duration = 120, tickInterval = 10, modifiers = new { stamina = 20, hunger = new { operation = "set", value = 100 }, healthRegeneration = 0.5 } });

Events.On("playerCustomBuffTick", (Player target, JsValue buff) =>
{
    Log.Info($"{buff["displayName"]} ticks on {target.Nickname}");
});

player.AddBuff(blessing);

claim.example:
// Injuries happen only when a script says so.
kcds.players.Buffs.claim(['injury']);

kcds.core.Events.on('playerBuffBlocked', (player, buff) => {
  console.info(`${buff} kept off ${player.nickname}`);
});

claim.exampleCs:
// Injuries happen only when a script says so.
Buffs.Claim(new[] { "injury" });

Events.On("playerBuffBlocked", (Player player, JsValue buff) =>
{
    Log.Info($"{buff} kept off {player.Nickname}");
});
